<script setup lang="ts">
import MoneyInput from './MoneyInput.vue';
import { ref, reactive, computed } from 'vue';
import { state, client, mutate, mutation, preferences, setTheme, today, resetDemo, logout, exportRemote, attachments, message } from '../store.ts';
import { demoArchive, download } from '../export.ts';
import { id, type Account, type Category, normalize } from '../domain.ts';
import { fromZonedTime } from '../timezone.ts';
import { parseMoney } from '../contracts.ts';
import Icon from './Icon.vue';
import Money from './Money.vue';
const emit = defineEmits<{ privacy: []; dirty: [value: boolean] }>();
const panel = ref(sessionStorage.getItem('danarapi.deletion.owner') ? 'privacy' : 'preferences'), editor = ref(''), busy = ref(false), error = ref(''), deletion = ref(''), existing = ref<Account | Category>();
const form = reactive({ name: '', kind: 'cash', amount: '0', date: today(), order: '0' });
const rule = reactive({ pattern: '', category: '', match: 'contains' });
const categories = computed(() => state.data.categories.filter(row => !row.archived && row.kind === 'expense'));
function edit(type: string, item?: Account | Category) { editor.value = type; existing.value = item; form.name = item?.name ?? ''; form.kind = item?.kind ?? (type === 'account' ? 'cash' : 'expense'); form.amount = item && 'openingBalance' in item ? item.openingBalance : '0'; form.date = item && 'openedAt' in item ? item.openedAt.slice(0,10) : today(); form.order = item && 'sortOrder' in item ? String(item.sortOrder) : String(state.data.categories.length); error.value = ''; }
async function save() {
  error.value = '';
  try {
    if (editor.value === 'account') parseMoney(form.amount, true);
    const payload = editor.value === 'account' ? existing.value ? { ...existing.value, name: form.name, kind: form.kind, openingBalance: form.amount, openedAt: fromZonedTime(form.date, state.timezone) } : { ...mutation(), p_name: form.name, p_kind: form.kind, p_opening_balance: form.amount, p_opened_at: fromZonedTime(form.date, state.timezone) } : existing.value ? { ...existing.value, name: form.name, sortOrder: Number(form.order) } : { ...mutation(), p_name: form.name, p_kind: form.kind, p_sort_order: Number(form.order) };
    if (await mutate(`${existing.value ? 'update' : 'create'}_${editor.value}`, payload)) editor.value = '';
  } catch (cause) { error.value = message(cause); }
}
async function archive(type: string, item: Account | Category) { if (window.confirm(`Arsipkan ${item.name}? Riwayat tetap tersimpan.`)) await mutate(`archive_${type}`, { id: item.id, expected_version: item.version }, 'Diarsipkan; riwayat tetap tersedia.'); }
async function exportAll() {
  if (!window.confirm('Ekspor penuh berisi informasi sensitif, termasuk lampiran. Simpan dan bagikan hanya di tempat aman.')) return;
  busy.value = true; error.value = '';
  try { const archive = state.mode === 'demo' ? await demoArchive(state.data, attachments) : await exportRemote(); download(state.mode === 'demo' ? 'danarapi-demo.zip' : 'danarapi-export.zip', archive); state.notice = state.mode === 'demo' ? 'Data contoh diunduh, bukan data server.' : 'Ekspor penuh diunduh.'; } catch (cause) { error.value = message(cause); } finally { busy.value = false; }
}
async function reauthenticate(provider: 'google') {
  if (!client) return;
  const { data: { session } } = await client.auth.getSession();
  if (!session) return;
  sessionStorage.setItem('danarapi.deletion.owner', session.user.id);
  const { error: failure } = await client.auth.signInWithOAuth({ provider, options: { redirectTo: window.location.origin + window.location.pathname + '#settings' } });
  if (failure) { sessionStorage.removeItem('danarapi.deletion.owner'); error.value = message(failure); }
}
async function deleteAccount() {
  if (state.mode === 'demo') { error.value = 'Mode Demo tidak memiliki akun server untuk dihapus.'; return; }
  if (!client || deletion.value !== 'HAPUS' || !window.confirm('Data Anda akan dihapus permanen setelah proses selesai. Akun, catatan, dan lampiran tidak dapat dipulihkan melalui aplikasi. Lanjutkan?')) return;
  busy.value = true; error.value = '';
  try {
    const expectedOwner = sessionStorage.getItem('danarapi.deletion.owner');
    const { data: { session } } = await client.auth.getSession();
    if (!expectedOwner || session?.user.id !== expectedOwner) throw new Error('Konfirmasi Google dengan akun yang sama terlebih dahulu.');
    if (await mutate('request_account_deletion', { expected_user_id: sessionStorage.getItem('danarapi.deletion.owner') }, 'Penghapusan selesai')) { await client.auth.signOut({ scope: 'local' }); await logout(); sessionStorage.removeItem('danarapi.deletion.owner'); state.notice = 'Penghapusan akun selesai dan dikonfirmasi server.'; }
  } catch (cause) { error.value = message(cause); } finally { busy.value = false; }
}
async function addRule() { if (!normalize(rule.pattern) || !rule.category) return; if (await mutate('save_merchant_rule', { id: id(), matchType: rule.match, normalizedPattern: normalize(rule.pattern), categoryID: rule.category, priority: 10, version: 0 })) rule.pattern = ''; }
</script>
<template><div class="settings-tabs button-row"><button v-for="tab in [['preferences','Preferensi'],['accounts','Akun'],['categories','Kategori'],['privacy','Data & privasi']]" :key="tab[0]" class="secondary" :class="{ selected: panel === tab[0] }" @click="panel = tab[0]; editor = ''">{{ tab[1] }}</button></div><p v-if="error || state.error" role="alert" class="error-text">{{ error || state.error }}</p><section v-if="panel === 'preferences'" class="card settings-section"><h2>Nyaman dengan caramu</h2><div class="profile-line"><span class="avatar mint">{{ state.mode === 'demo' ? 'D' : state.email.charAt(0).toUpperCase() }}</span><div><strong>{{ state.mode === 'demo' ? 'Teman Demo' : state.email }}</strong><p class="muted">{{ state.mode === 'demo' ? 'Data contoh, bebas mencoba' : 'Akun terverifikasi' }}</p></div></div><label>Tema<select :value="state.theme" @change="setTheme(($event.target as HTMLSelectElement).value)"><option value="system">Sistem</option><option value="light">Terang</option><option value="dark">Gelap</option></select></label><label>Zona waktu<select v-model="state.timezone" @change="preferences"><option>Asia/Jakarta</option><option>Asia/Makassar</option><option>Asia/Jayapura</option><option>UTC</option></select></label><label class="checkbox"><input v-model="state.hideAmounts" type="checkbox" @change="preferences"> Sembunyikan nominal</label><details class="help-disclosure"><summary>Penyimpanan perangkat</summary><p>Preferensi disimpan di perangkat. Data keuangan tidak disimpan di localStorage; sesi akun berlaku per tab.</p></details><div class="button-row"><button v-if="state.mode === 'demo'" class="secondary" @click="resetDemo"><Icon name="reset" /> Reset Demo</button><button class="secondary" @click="logout">{{ state.mode === 'demo' ? 'Keluar Demo' : 'Keluar' }}</button></div></section><section v-if="panel === 'accounts' || panel === 'categories'" class="card settings-section"><div class="section-heading"><h2>{{ panel === 'accounts' ? 'Akunmu' : 'Kategori catatan' }}</h2><button class="secondary" @click="edit(panel === 'accounts' ? 'account' : 'category')"><Icon name="plus" /> Tambah {{ panel === 'accounts' ? 'akun' : 'kategori' }}</button></div><p class="muted">{{ panel === 'accounts' ? 'Saldo catatan, bukan saldo bank.' : 'Arsip kategori tidak mengubah histori.' }}</p><form v-if="editor" class="entry-form inline-editor callout sky" @submit.prevent="save"><h3>{{ existing ? 'Ubah' : 'Tambah' }} {{ editor === 'account' ? 'akun' : 'kategori' }}</h3><div class="form-grid"><label>Nama<input v-model="form.name" maxlength="80" required></label><label>Jenis<select v-model="form.kind" :disabled="editor === 'category' && !!existing"><template v-if="editor === 'account'"><option value="cash">Tunai</option><option value="bank">Bank</option><option value="ewallet">E-wallet</option><option value="other">Lainnya</option></template><template v-else><option value="expense">Pengeluaran</option><option value="income">Pemasukan</option></template></select></label><template v-if="editor === 'account'"><label>Saldo awal<MoneyInput v-model="form.amount" required /></label><label>Tanggal pembukaan<input v-model="form.date" type="date" required></label></template><label v-else>Urutan<input v-model="form.order" type="number" min="0" max="9999" required></label></div><div class="button-row"><button class="primary" :disabled="state.saving">Simpan</button><button type="button" class="secondary" @click="editor = ''">Batal</button></div></form><div v-if="panel === 'accounts'"><div v-for="account in state.data.accounts" :key="account.id" class="list-row"><span class="icon-tile sky"><Icon :name="account.kind === 'bank' ? 'bank' : 'wallet'" /></span><div class="row-copy"><strong>{{ account.name }}</strong><span>{{ account.archived ? 'Diarsipkan' : 'Aktif' }} · {{ account.kind }}</span></div><Money :amount="account.balance" /><button class="icon-button" :aria-label="`Ubah akun ${account.name}`" @click="edit('account', account)"><Icon name="edit" /></button><button v-if="!account.archived" class="icon-button" :aria-label="`Arsipkan akun ${account.name}`" :disabled="state.saving || state.data.accounts.filter(row => !row.archived).length <= 1" @click="archive('account', account)"><Icon name="trash" /></button></div></div><div v-else><div v-for="category in [...state.data.categories].sort((left,right) => left.sortOrder - right.sortOrder)" :key="category.id" class="list-row"><div class="row-copy"><strong>{{ category.name }}</strong><span>{{ category.kind === 'income' ? 'Pemasukan' : 'Pengeluaran' }} · {{ category.archived ? 'Diarsipkan' : 'Aktif' }} · urutan {{ category.sortOrder }}</span></div><button class="icon-button" :aria-label="`Ubah kategori ${category.name}`" @click="edit('category', category)"><Icon name="edit" /></button><button v-if="!category.archived" class="icon-button" :aria-label="`Arsipkan kategori ${category.name}`" :disabled="state.saving" @click="archive('category', category)"><Icon name="trash" /></button></div><h3>Aturan merchant</h3><form class="entry-form" @submit.prevent="addRule"><div class="form-grid"><label>Pola merchant<input v-model="rule.pattern" required maxlength="160" placeholder="warung"></label><label>Pencocokan<select v-model="rule.match"><option value="contains">Mengandung</option><option value="exact">Persis</option><option value="prefix">Diawali</option></select></label><label>Kategori<select v-model="rule.category" required><option value="" disabled>Pilih kategori</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select></label></div><button class="secondary" :disabled="state.saving">Tambah aturan</button></form><div v-for="item in state.data.merchantRules" :key="item.id" class="list-row"><span>{{ item.normalizedPattern }} · {{ state.data.categories.find(row => row.id === item.categoryID)?.name }}</span><button class="text-button danger-text" :disabled="state.saving" @click="mutate('delete_merchant_rule', { id: item.id, expected_version: item.version })">Hapus</button></div></div></section><section v-if="panel === 'privacy'" class="card settings-section"><h2>Datamu tetap milikmu</h2><p>Unduh catatan dan lampiran. File ekspor berisi data sensitif.</p><button class="secondary" :disabled="busy" @click="exportAll"><Icon name="download" />{{ busy ? 'Menyiapkan ekspor…' : 'Ekspor penuh (ZIP)' }}</button><button class="text-button" @click="emit('privacy')">Baca kebijakan privasi</button><hr><h3 class="danger-text">Hapus akun</h3><p>Data Anda akan dihapus permanen setelah proses selesai. Data aplikasi, lampiran, serta sesi dihapus; retensi cadangan mengikuti konfigurasi penyedia dan belum diverifikasi untuk publikasi.</p><p v-if="state.mode === 'demo'" class="callout sun">Mode Demo tidak memiliki akun server. Gunakan Reset Demo atau Keluar Demo.</p><form v-else class="entry-form" @submit.prevent="deleteAccount"><div class="button-row"><button type="button" class="secondary" :disabled="busy" @click="reauthenticate('google')">Konfirmasi Google</button></div><label>Ketik HAPUS untuk melanjutkan<input v-model="deletion" autocomplete="off" pattern="HAPUS" required></label><button class="danger" :disabled="busy || state.saving || deletion !== 'HAPUS'">{{ busy ? 'Penghapusan sedang diproses…' : 'Hapus akun permanen' }}</button></form></section></template>
